<script>(function(){var tb=document.querySelector('table[data-tc="alert_rules"]');if(!tb)return;var EN=(typeof LANG!=='undefined'&&LANG==='en'),f=document.getElementById('gform'),TOK=<?= json_encode(csrf()) ?>;
