function hdr(r){while(r&&!r.classList.contains('grph'))r=r.previousElementSibling;return r}
function cnt(){[].forEach.call(tb.querySelectorAll('tr.grph'),function(h){var c=h.querySelector('.gcn');if(c)c.textContent=rowsOf(h).length})}
[].forEach.call(tb.querySelectorAll('tr.grph'),function(h){var gid=h.dataset.gid,k='vm_agc_'+gid;function apply(c){h.querySelector('.gtg').textContent=c?'▸':'▾';rowsOf(h).forEach(function(r){r.hidden=c});h.dataset.c=c?'1':''}
 var c=false;try{c=localStorage.getItem(k)==='1'}catch(e){}apply(c);
 h.addEventListener('click',function(e){var ga=e.target.closest('[data-ga]');if(ga){e.preventDefault();e.stopPropagation();var a=ga.dataset.ga;
