   function done(){box.remove();b.style.display=''}function save(){var n=inp.value.trim();if(n&&n!==old)post('grp_ren',gid,n);else done()}
   box.querySelector('.go').onclick=function(ev){ev.stopPropagation();save()};box.querySelectorAll('button')[1].onclick=function(ev){ev.stopPropagation();done()};inp.onclick=function(ev){ev.stopPropagation()};inp.onkeydown=function(ev){ev.stopPropagation();if(ev.key==='Enter'){ev.preventDefault();save()}else if(ev.key==='Escape')done()}}
  else if(a==='del'){var act=ga.parentNode,orig=act.innerHTML,q=document.createElement('span');q.innerHTML=(EN?'Delete this group? The rules are kept and move to "Ungrouped". ':'Ta bort gruppen? Reglerna behålls och flyttas till "Ej grupperade". ')+'<button type="button" class="btn sm danger">'+(EN?'Delete':'Ta bort')+'</button> <button type="button" class="btn sm">'+(EN?'Cancel':'Avbryt')+'</button>';act.innerHTML='';act.appendChild(q);
   q.querySelector('.danger').onclick=function(ev){ev.stopPropagation();post('grp_del',gid)};q.querySelectorAll('button')[1].onclick=function(ev){ev.stopPropagation();act.innerHTML=orig}}return}
  var cl=h.dataset.c!=='1';apply(cl);try{localStorage.setItem(k,cl?'1':'0')}catch(e){}})});
